import { SvgXml } from 'react-native-svg';
import { View, ViewStyle } from 'react-native';
import { Buffer } from 'buffer';

const xml = Buffer.from('', 'base64').toString('utf8');

export function BrandLogo({ width = 180, height = 72, style }: { width?: number; height?: number; style?: ViewStyle }) {
  return (
    <View style={[{ width, height, backgroundColor: 'transparent' }, style]} accessible accessibilityRole="image" accessibilityLabel="ViaJunto">
      <SvgXml xml={xml} width="100%" height="100%" />
    </View>
  );
}